//! Machine-readable, reference-verified coverage accounting for Nabu MBNv6.
//! Every reported source-generated byte is produced by typed metadata/code;
//! no original executable, hash/signature or certificate bytes are included.
//! BSS is reported as memory-only. An intact reference's digest table and
//! embedded OEM signatures are *not* independent firmware reconstruction.
use std::ops::Range;
use crate::{devices::xiaomi_nabu::a640_container,
    elf32_prefix::Elf32Spec,elf_file_coverage::compare_known_first_page,
    image_plan::CoverageReport,qcom_mbn_profiles::unsigned_metadata_plan,
    qcom_mbn_validation::verify_elf32_mbnv6_hashes};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MbnCoverageManifest {
    pub image_name: &'static str,
    pub total_file_bytes: usize,
    pub independently_generated_file_bytes: usize,
    pub externally_supplied_file_bytes: usize,
    pub missing_file_bytes: usize,
    pub first_missing_range: Option<Range<usize>>,
    pub hash_segment_file_range: Range<usize>,
    pub oem_authentication_file_range: Range<usize>,
    pub reference_sha384_hashed_segments: usize,
    pub memory_only_bss_bytes: u64,
    pub executable_file_ranges: Vec<Range<usize>>,
}

impl MbnCoverageManifest {
    /// Format-only JSON serialization: image_name comes from the fixed,
    /// trusted known-spec table; no untrusted strings are interpolated.
    /// Offsets are decimal numbers so command-line JSON consumers can compare
    /// and merge source coverage without depending on presentation strings.
    pub fn to_json(&self) -> String {
        let first = match &self.first_missing_range {
            Some(span) => format!("{{\"start\":{},\"end\":{}}}",span.start,span.end),
            None => "null".to_owned(),
        };
        let executable = self.executable_file_ranges.iter()
            .map(|r| format!("[{},{}]",r.start,r.end))
            .collect::<Vec<_>>().join(",");
        format!(concat!(
            "{{\"image\":\"{}\",\"file_bytes\":{},",
            "\"independently_generated_file_bytes\":{},",
            "\"externally_supplied_authentication_bytes\":{},",
            "\"missing_file_bytes\":{},\"first_missing_file_range\":{},",
            "\"hash_segment_file_range\":[{},{}],",
            "\"original_oem_authentication_file_range\":[{},{}],",
            "\"reference_sha384_hashed_segments\":{},",
            "\"memory_only_bss_bytes\":{},\"executable_file_ranges\":[{}],",
            "\"hardware_trust_verified\":false}}"
        ),self.image_name,self.total_file_bytes,self.independently_generated_file_bytes,
           self.externally_supplied_file_bytes,self.missing_file_bytes,first,
           self.hash_segment_file_range.start,self.hash_segment_file_range.end,
           self.oem_authentication_file_range.start,self.oem_authentication_file_range.end,
           self.reference_sha384_hashed_segments,self.memory_only_bss_bytes,executable)
    }
}

/// Check the exact source-describable image bytes *first*, then audit original
/// SHA-384 consistency. For A640 use its stronger existing independently
/// authored executable+hash+padding reconstruction (7,856 bytes); the other
/// MBNs currently have header+policy coverage (4,264 bytes each).
/// Does not import OEM authentication or vendor program bytes into the plan.
pub fn audit_reference(
    spec: &Elf32Spec, reference: &[u8],
) -> Result<MbnCoverageManifest,String> {
    let inventory=compare_known_first_page(spec,reference)?;
    let plan = if spec.name=="a640_zap.mbn" {
        a640_container::partial_container()?
    } else {
        unsigned_metadata_plan(spec,reference.len())?
    };
    plan.compare_known(reference)?;
    let coverage:CoverageReport=plan.coverage();
    if coverage.externally_supplied_bytes != 0 {
        return Err("source-generated manifest unexpectedly contains externally supplied bytes".into());
    }
    let hashes=verify_elf32_mbnv6_hashes(reference)?;
    let hash_start=inventory.authentication_file_range.start;
    if hashes.hash_segment_file_offset!=hash_start {
        return Err("signed MBNv6 hash segment differs from known ELF header".into());
    }
    let signing_start=hash_start.checked_add(hashes.signed_layout.oem_signature.start)
        .ok_or("OEM signature file start overflow")?;
    let signing_end=hash_start.checked_add(hashes.signed_layout.oem_certificate.end)
        .ok_or("OEM certificate file end overflow")?;
    if signing_end>inventory.authentication_file_range.end {
        return Err("OEM authentication extent outside declared ELF signed region".into());
    }
    if !hashes.has_signatures || signing_start>=signing_end {
        return Err("expected original MBNv6 OEM authentication field".into());
    }
    Ok(MbnCoverageManifest {
        image_name:spec.name,
        total_file_bytes:reference.len(),
        independently_generated_file_bytes:coverage.generated_bytes,
        externally_supplied_file_bytes:coverage.externally_supplied_bytes,
        missing_file_bytes:coverage.missing_bytes,
        first_missing_range:coverage.holes.first().cloned(),
        hash_segment_file_range:inventory.authentication_file_range,
        oem_authentication_file_range:signing_start..signing_end,
        reference_sha384_hashed_segments:hashes.hashed_count,
        memory_only_bss_bytes:inventory.zero_fill_memory_bytes,
        executable_file_ranges:inventory.executable_file_ranges,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::devices::xiaomi_nabu::{a640_container,elf_specs::KNOWN_ELFS};

    #[test]
    fn synthetic_a640_reference_reports_generated_vs_authentication() {
        // The original OEM material is not required for coverage testing.
        let b=a640_container::assemble_with_external_authentication(&vec![0x44;6400]).unwrap();
        let spec=KNOWN_ELFS.iter().find(|s|s.name=="a640_zap.mbn").unwrap();
        let manifest=audit_reference(spec,&b).unwrap();
        assert_eq!(manifest.total_file_bytes,14_256);
        assert_eq!(manifest.independently_generated_file_bytes,7_856);
        assert_eq!(manifest.externally_supplied_file_bytes,0);
        assert_eq!(manifest.missing_file_bytes,6_400);
        assert_eq!(manifest.first_missing_range,Some(0x1138..0x2a38));
        assert_eq!(manifest.oem_authentication_file_range,0x1138..0x2a38);
        assert_eq!(manifest.reference_sha384_hashed_segments,2);
        assert!(manifest.to_json().contains("\"hardware_trust_verified\":false"));
        assert!(manifest.to_json().contains("\"first_missing_file_range\":{\"start\":4408"));
    }
    #[test]
    fn mutated_generated_bytes_or_hashes_fail_coverage_audit() {
        let mut image=a640_container::assemble_with_external_authentication(&vec![0x44;6400]).unwrap();
        let spec=KNOWN_ELFS.iter().find(|s|s.name=="a640_zap.mbn").unwrap();
        image[0x10]^=1;
        assert!(audit_reference(spec,&image).is_err());
        image[0x10]^=1;
        image[0x1100]^=1; // digest/metadata field, not independent executable
        assert!(audit_reference(spec,&image).is_err());
        image[0x1100]^=1;
        image.pop();
        assert!(audit_reference(spec,&image).is_err());
    }
}
